const multi=[...g.entries()].filter(([k,a])=>a.length>1);
const sizes=[...g.values()].reduce((m,a)=>{m[a.length]=(m[a.length]||0)+1;return m},{});
const targets=[...g.entries()].filter(([k,a])=>a.length>1 && a.every(x=>x.dup==='Yes' && x.rel!=='Employee'));
const singles=[...g.entries()].filter(([k,a])=>a.length==1);
({sizes,targets,singles, blanks: wb.getRange("SwiftMD!B3:B42").getCounts?.()})

