const s = wb.getWorksheet('SwiftMD');
const t = s.getTables ? s.getTables()[0] : null;
const v = wb.getRange("SwiftMD!C3:H42").getValues();
const g = new Map();
v.forEach((r,i)=>{const k=JSON.stringify([r[0],r[1],r[3]]);(g.get(k)||g.set(k,[]).get(k)).push({i,dup:r[4],rel:r[5]});});
const del=[...g.values()].filter(a=>a.length>1 && a.every(x=>x.dup==='Yes' && x.rel!=='Employee')).map(a=>a[a.length-1].i).sort((a,b)=>b-a);
log('deleting rows', del.map(i=>i+3).join(','), v.length);
del.forEach(i=>t.deleteRowsAt(i,1));
log(t.getRange().getA1?.());
wb.getRange("SwiftMD!B2:O44")

